module protocol::market;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::balance::Balance;
use sui::clock::Clock;
use sui::coin::{Self, Coin};
use sui::dynamic_field;
use sui::object_table::{Self, ObjectTable};

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::{get_price, get_price_with_check};

use math::float::{Self, Decimal};
use protocol::generic_store::{Self, GenericCoinTypeStorage};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;

use protocol::asset::{Self, Asset, AssetConfig};
use protocol::error;
use protocol::interest::InterestModel;
use protocol::obligation::Obligation;
use protocol::reserve::{Self, Reserve, ReserveFlashLoan};
use protocol::value::coin_value;
use protocol::emode::{Self, EModeGroup, EModeGroupRegistry};
use protocol::adl::{new_auto_deleverage_registry, AutoDeleverageRegistry};
use protocol::liquidity_miner::{Self, LiquidityMiner};
use x_oracle::user_oracle::get_spot_price;

const DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS: u64 = 1000; // 10%
const DEFAULT_EMA_SPOT_DIFF_DENOMINATOR: u64 = 10000;

public struct MarketConfiguration has store, copy, drop {
    close_factor: Decimal,
    close_factor_bypass_min_value: u64,
}

/// Flash loan hot potato
public struct FlashLoan<phantom MarketType, phantom CoinType> {
    inner: ReserveFlashLoan<MarketType, CoinType>,
    fee: u64,
}

public fun loan_amount<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.inner.amount()
}

public fun fee<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.fee
}

// a default emode group for lending
public(package) fun lending_default_emode_group(): u8 { 0 }

public struct Market<phantom MarketType> has key, store {
    id: UID,

    assets: GenericCoinTypeStorage<Asset<MarketType>>,
    reserves: GenericCoinTypeStorage<Reserve<MarketType>>,

    /// The max price tolerance between ema and spot price. If the difference is more than this value
    /// borrow and withdraw will be rejected, default to 10% per asset.
    ema_spot_tolerance: GenericCoinTypeStorage<Decimal>,

    emode_group_registry: EModeGroupRegistry,

    obligations: ObjectTable<ID, Obligation<MarketType>>,

    liquidity_miner: LiquidityMiner<MarketType>,

    // dynamic fields:
    // - circuit_break
    // - market_config
    // - adl_registry
}

// dynamic field keys
public struct MarketConfigurationKey has copy, drop, store {}
public struct CircuitBreakKey has copy, drop, store {}
public struct ADLRegistryKey has copy, drop, store {}

